-- Install the attached template as editable content / routing settings.
-- Does not alter validated wording, answer IDs, saved results or attempt history.
SET LOCAL lock_timeout = '5s';
CREATE TABLE assessment_settings (
  id boolean PRIMARY KEY DEFAULT TRUE CHECK (id = TRUE),
  settings jsonb NOT NULL CHECK (jsonb_typeof(settings) = 'object'),
  updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
ALTER TABLE assessment_settings ENABLE ROW LEVEL SECURITY;
