UPDATE assessment_questions q SET
  routing_config = q.routing_config || jsonb_build_object('sectionId', item->>'sectionId'),
  updated_at = CURRENT_TIMESTAMP
FROM jsonb_array_elements($sections$[{"id":"4e80919c-11a3-433c-9a82-43fcbdd15787","sectionId":"academic"},{"id":"e8bd2343-ff1d-4b1e-a749-ad9678e9c2aa","sectionId":"academic"},{"id":"e89c46e4-a8b9-4f8e-a1e5-69c7db1434a5","sectionId":"academic"},{"id":"21028771-aa1c-47ad-afe9-61070968e991","sectionId":"academic"},{"id":"61f60e66-cc63-45af-b2ff-eb54f79346f3","sectionId":"academic"},{"id":"30b8c263-7363-4da3-81e6-8c9228504119","sectionId":"career"},{"id":"08d67579-3d6d-4d4d-bfdb-d9c9beb2e24e","sectionId":"career"},{"id":"df1f303f-0889-4a92-94a7-36fdab20b199","sectionId":"career"},{"id":"4b667ad6-67db-427a-ac72-3ceda2abde22","sectionId":"career"},{"id":"b49b59a5-2906-49db-8918-78d75af6db2b","sectionId":"career"},{"id":"077dc854-8d5d-431d-9bfd-0e4a6380a3d7","sectionId":"learning"},{"id":"26372c25-b976-44f8-b84f-abf9b7cae1f0","sectionId":"learning"},{"id":"591d3857-0414-4def-9545-83b11b2bc30f","sectionId":"learning"},{"id":"73ccff17-fb49-475b-9335-0d599c0f41f5","sectionId":"learning"},{"id":"f966128a-073e-4e71-ad10-f396b6ddfe86","sectionId":"learning"},{"id":"58cb66ff-95e7-479d-80f6-0d4a075ac9c9","sectionId":"practical"},{"id":"f64ae175-86b2-4d59-aa01-a8949771e025","sectionId":"practical"},{"id":"700f406e-f0f6-4bd4-b6c0-fea3421f8b23","sectionId":"practical"},{"id":"0a57a6bc-6071-4477-afeb-56d7c8b8a17b","sectionId":"practical"},{"id":"31d0857c-fcba-40ee-b04a-46934992c657","sectionId":"practical"}]$sections$::jsonb) item
WHERE q.question_id = item->>'id' AND q.routing_config IS NOT NULL AND NOT (q.routing_config ? 'sectionId');
-- Q9's answer-to-profile order in the supplied template is A/D/C/B.
-- Preserve a previously customized admin mapping rather than overwriting it.
UPDATE assessment_questions SET options = (
  SELECT jsonb_agg(answer || jsonb_build_object('macro', mapped->>'macro') ORDER BY ordinality)
  FROM jsonb_array_elements(options) WITH ORDINALITY source(answer, ordinality)
  JOIN jsonb_array_elements($mapping$[{"id":"bfe6921d-d9cc-4fbf-aca7-612e7b654109","macro":"A"},{"id":"48ba42bd-43d8-4d98-bfe0-f619f041b146","macro":"D"},{"id":"20c650fb-8ca4-4bc4-a0e0-1344c6f3d747","macro":"C"},{"id":"9a1e05e6-cb2d-40dd-89d3-1003a8d61167","macro":"B"}]$mapping$::jsonb) mapped
    ON answer->>'id' = mapped->>'id'
), updated_at = CURRENT_TIMESTAMP
WHERE question_id = '4b667ad6-67db-427a-ac72-3ceda2abde22' AND routing_config->>'role' = 'macro-vote'
  AND ARRAY(SELECT answer->>'macro' FROM jsonb_array_elements(options) answer) = ARRAY['A','B','C','D']
  AND prompt = '9. How interested are you in working with numbers and data?'
  AND jsonb_array_length(options) = 4
  AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements($original$[{"id":"bfe6921d-d9cc-4fbf-aca7-612e7b654109","label":"very interested; I enjoy analyzing numbers, patterns, and data"},{"id":"48ba42bd-43d8-4d98-bfe0-f619f041b146","label":"moderately interested; I enjoy using data when solving practical problems"},{"id":"20c650fb-8ca4-4bc4-a0e0-1344c6f3d747","label":"slightly interested; I use numbers and data only when needed"},{"id":"9a1e05e6-cb2d-40dd-89d3-1003a8d61167","label":"not interested; I prefer work with little or no numbers and data"}]$original$::jsonb) expected
    WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(options) current
      WHERE current->>'id' = expected->>'id' AND current->>'label' = expected->>'label'));
